/* Which ROM and verification vector the SD/ROM modes use.
 *
 * Selected at configure time with -D GBA_ROM_PROFILE=<name> (default gs1);
 * firmware/main/CMakeLists.txt turns it into GBA_ROM_PROFILE_<NAME>=1. Each
 * profile carries the ROM's path, size and SHA-256, and the per-frame CRC
 * verification vector generated by tools/gen_frame_crcs.py from the host
 * reference runner.
 *
 * The SHA-256 is checked against what is actually read from the card, so a
 * missing, renamed or different ROM fails loudly instead of producing a bogus
 * pass. Verification vectors are not ROM content and are safe to commit.
 *
 * Include gba_sd.h first: paths are built from GBA_SD_MOUNT_POINT.
 */
#pragma once

#ifndef GBA_SD_MOUNT_POINT
#error "include gba_sd.h before gba_rom_profile.h"
#endif

#if defined(GBA_ROM_PROFILE_GS1) && defined(GBA_ROM_PROFILE_FFTA)
#error "exactly one ROM profile must be selected"
#endif

#if defined(GBA_ROM_PROFILE_GS1)

#define GBA_ROM_LABEL "Golden Sun 1 (Japan)"
#define GBA_ROM_PATH GBA_SD_MOUNT_POINT "/gba/OugonNoTaiyouHirakareshiFuuin.gba"
#define GBA_ROM_SIZE 8388608u
#define GBA_ROM_SHA256 \
    "088bedae4bad8b67e87ff10035a898d3639f3182d486fe5a5d113bab223e0a26"

#include "gba_gs1_frame_crcs.h"
#define GBA_ROM_CRC_COUNT GBA_GS1_FRAME_COUNT
#define GBA_ROM_FRAME_CRC gba_gs1_frame_crc
#define GBA_ROM_GOLDEN_CRC_FRAME1 0x22bafa3au
#define GBA_ROM_GOLDEN_CRC_FRAME60 0x89e57f72u
#define GBA_ROM_GOLDEN_CRC_LAST 0x0674d5f9u

#elif defined(GBA_ROM_PROFILE_FFTA)

#define GBA_ROM_LABEL "Final Fantasy Tactics Advance (Japan)"
#define GBA_ROM_PATH GBA_SD_MOUNT_POINT "/gba/FFTA.jp.gba"
#define GBA_ROM_SIZE 16777216u
#define GBA_ROM_SHA256 \
    "b13dd536808ef5d0fd4494386a9499f6feb8310835d3f867cd17cc340d82bf9a"

#include "gba_ffta_frame_crcs.h"
#define GBA_ROM_CRC_COUNT GBA_FFTA_FRAME_COUNT
#define GBA_ROM_FRAME_CRC gba_ffta_frame_crc
#define GBA_ROM_GOLDEN_CRC_FRAME1 0xb5532989u
#define GBA_ROM_GOLDEN_CRC_FRAME60 0x0eaadad0u
#define GBA_ROM_GOLDEN_CRC_LAST 0x40ce7f1fu

#else
#error "no ROM profile selected (define GBA_ROM_PROFILE_GS1 or GBA_ROM_PROFILE_FFTA)"
#endif

/* The frame count every profile's vector is generated for. */
#ifndef GBA_ROM_FRAME_COUNT
#define GBA_ROM_FRAME_COUNT 600u
#endif

_Static_assert(GBA_ROM_CRC_COUNT == GBA_ROM_FRAME_COUNT,
               "profile CRC vector length must equal GBA_ROM_FRAME_COUNT");
